@page "/settings"
@rendermode InteractiveServer
@using sv_cb432eda08e74e0ea4f0b5b937018ccf.Services
@namespace sv_cb432eda08e74e0ea4f0b5b937018ccf.Components.Pages.Settings
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="container-fluid py-4">
    <h2 class="mb-4">Settings</h2>
    <div class="row">
        <div class="col-md-3 col-lg-2">
            <SettingsSidebar ActiveSection="@_activeSection" OnSectionSelected="SetSection" />
        </div>
        <div class="col-md-9 col-lg-10">
            @switch (_activeSection)
            {
                case "Profile":
                    <ProfileSection SettingsService="SettingsService" />
                    break;
                case "Notifications":
                    <NotificationsSection SettingsService="SettingsService" />
                    break;
                case "Security":
                    <SecuritySection SettingsService="SettingsService" />
                    break;
                case "Appearance":
                    <AppearanceSection SettingsService="SettingsService" />
                    break;
            }
        </div>
    </div>
</div>

@code {
    private string _activeSection = "Profile";

    private void SetSection(string section) => _activeSection = section;
}

.settings-sidebar .nav-link {
    border-radius: 0.375rem;
    margin-bottom: 0.25rem;
    color: #495057;
    border: none;
    background: none;
    width: 100%;
    padding: 0.5rem 1rem;
}

.settings-sidebar .nav-link:hover {
    background-color: #e9ecef;
}

.settings-sidebar .nav-link.active {
    background-color: #0d6efd;
    color: #fff;
}

